// scanningText is what Scanned says while a scan runs on the row.
const scanningText = "scanning"

// rowsFor decorates the entries with the scan state the table shows.
func (m *Model) rowsFor(entries []Entry) []workspaceRow {
	rows := make([]workspaceRow, 0, len(entries))
	for _, entry := range entries {
		sensitive, misc, c, h, med, l, scanned := m.formatScanColumns(entry)
		gitStatus := formatGitStatus(entry)
		branchCut := utf8.RuneCountInString(displayBranch(entry.GitBranch))
		held := false
		// A row can only be held by one of the two — busy() is what keeps them
		// apart — so the order below decides nothing. The delete spends this
		// cell for the same reason the sync does, and with less to lose: a
		// directory on its way out has no git status left to announce.
		switch {
		case m.runningKind(jobs.KindDelete, entry.Path):
			gitStatus, held = "deleting", true
		case m.runningKind(jobs.KindSync, entry.Path):
			gitStatus, held = "syncing", true
		}
		if held {
			branchCut = utf8.RuneCountInString(gitStatus)
		}
		rows = append(rows, workspaceRow{
			Entry:     entry,
			Activity:  m.rowActivity(entry),
			GitStatus: gitStatus,
			branchCut: branchCut,
			held:      held,
// For directories: aggregates sub-repo scan entries.
func (m *Model) formatScanColumns(entry Entry) (sensitive secretsCell, misc misconfigCell, c, h, med, l, scanned string) {
	dash := "-"
	empty := ""
	none := secretsCell{}
	unscanned := secretsCell{Text: dash}
	// A row with no verdict at all: the same three cases the Secrets column
	// spells with `none` and `unscanned`, one column over.
	noMisc := misconfigCell{}
	unscannedMisc := misconfigCell{Text: dash}

	if entry.IsGitRepo {
		if m.runningKind(jobs.KindScan, entry.Path) {
			return none, unscannedMisc, dash, dash, dash, dash, scanningText
		}
		scanEntry, ok := m.scanCache[entry.Path]
		if !ok {
			return unscanned, unscannedMisc, dash, dash, dash, dash, dash
		}
		return secretsFor(theme.SecretsVerdict(scanEntry.Sensitive, true)),
			misconfigFor(scanEntry.Misconfig, true),
			fmt.Sprintf("%d", scanEntry.Critical),
			fmt.Sprintf("%d", scanEntry.High),
			fmt.Sprintf("%d", scanEntry.Medium),
			fmt.Sprintf("%d", scanEntry.Low),
			theme.IconPending + " " + timeAgo(scanEntry.ScannedAt)
	}

	// Files are not scannable — return empty columns
	if !entry.IsDir {
		return none, noMisc, empty, empty, empty, empty, empty
	}

	// Directory: aggregate sub-repos
	if len(entry.SubRepoPaths) == 0 {
		return secretsFor(theme.SecretsUnknown), noMisc, empty, empty, empty, empty, empty
	}

	// Count how many sub-repos are currently scanning
	scanningCount := 0
	for _, repoPath := range entry.SubRepoPaths {
		if m.runningKind(jobs.KindScan, repoPath) {
			scanningCount++
		}
	}

	var scannedEntries []cache.WorkspaceScanEntry
	for _, repoPath := range entry.SubRepoPaths {
		if e, ok := m.scanCache[repoPath]; ok {
			scannedEntries = append(scannedEntries, e)
		}
	}

	if scanningCount == 0 && len(scannedEntries) == 0 {
		return unscanned, unscannedMisc, empty, empty, empty, empty, dash
	}
